<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Tenant; use App\Services\AuditService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class TenantController extends Controller { public function index(Request $r):JsonResponse{return $this->success(['items'=>Tenant::query()->where('organization_id',$r->attributes->get('organization_id'))->orderBy('full_name')->get()->map(fn($t)=>$this->data($t))]);} public function show(Request $r,string $id):JsonResponse{return $this->success($this->data($this->find($r,$id)));} public function store(Request $r):JsonResponse{$d=$r->validate(['tenantCode'=>['required','string','max:50'],'fullName'=>['required','string','max:200'],'nationalIdOrIqama'=>['required','string','max:50'],'mobilePrimary'=>['required','string','max:30'],'email'=>['nullable','email']]);$org=$r->attributes->get('organization_id');$t=Tenant::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'code'=>$d['tenantCode'],'full_name'=>$d['fullName'],'national_id_or_iqama'=>$d['nationalIdOrIqama'],'mobile'=>$d['mobilePrimary'],'email'=>$d['email']??null]);AuditService::record($org,$r->user()->id,'tenant.created','tenant',$t->id,null,$this->data($t));return $this->success($this->data($t),[],201);} public function update(Request $r,string $id):JsonResponse{$d=$r->validate(['fullName'=>['sometimes','string','max:200'],'mobilePrimary'=>['sometimes','string','max:30'],'email'=>['nullable','email'],'status'=>['sometimes','in:active,inactive,archived'],'version'=>['required','integer']]);$org=$r->attributes->get('organization_id');$t=DB::transaction(function()use($r,$id,$d,$org){$t=$this->find($r,$id,true);if($t->version!==$d['version'])abort(409,'تم تعديل المستأجر من مستخدم آخر.');$before=$this->data($t);$t->fill(['full_name'=>$d['fullName']??$t->full_name,'mobile'=>$d['mobilePrimary']??$t->mobile,'email'=>$d['email']??$t->email,'status'=>$d['status']??$t->status]);$t->version++;$t->save();AuditService::record($org,$r->user()->id,'tenant.updated','tenant',$t->id,$before,$this->data($t));return $t;});return $this->success($this->data($t));} private function find(Request $r,string $id,bool $lock=false):Tenant{$q=Tenant::query()->where('organization_id',$r->attributes->get('organization_id'));if($lock)$q->lockForUpdate();return $q->findOrFail($id);} private function data(Tenant $t):array{return ['id'=>$t->id,'tenantCode'=>$t->code,'fullName'=>$t->full_name,'nationalIdOrIqama'=>$t->national_id_or_iqama,'mobilePrimary'=>$t->mobile,'email'=>$t->email,'status'=>$t->status,'version'=>$t->version];}}
